//! `cli/internal/completions/fish` witnesses for
//! `packages/effect/test/cli/completions/completions.test.ts` (Fish section).
//!
//! The oracle is the pin itself: each fixture's script was generated by the
//! upstream `fish.ts` and committed under `fixtures/completions/fish/`, so the
//! byte-equality test below is stricter than the pin's `assert.include` rows.
//! Each `#[test]` names the upstream line it proves.

mod completions_fixtures;

use completions_fixtures::{
    backslash_desc, choices, comprehensive, fish_goldens, nested, noop, paths, scoped, server,
    simple, tricky,
};
use elm_effect_unstable::cli_completions::fish;

/// The pin's own generator output, byte for byte. This subsumes the
/// `assert.include` rows below; the per-row tests stay for ledger traceability.
#[test]
fn fish_script_matches_pin_goldens_byte_for_byte() {
    for (fixture, executable, descriptor, golden) in fish_goldens() {
        assert_eq!(
            fish::generate(executable, &descriptor()),
            golden,
            "fish script for fixture `{fixture}` diverged from the pin"
        );
    }
}

// ---------------------------------------------------------------------------
// Rows from `completions.test.ts`, Fish section.
// ---------------------------------------------------------------------------

#[test]
fn scopes_nested_completions_by_the_full_command_path() {
    // :552
    let script = fish::generate("tool", &scoped());
    let lines: Vec<&str> = script.lines().collect();
    let alpha = lines
        .iter()
        .find(|line| line.contains("-l alpha-only"))
        .expect("alpha-only entry missing");
    let beta = lines
        .iter()
        .find(|line| line.contains("-l beta-only"))
        .expect("beta-only entry missing");
    assert!(
        alpha.contains("__fish_seen_subcommand_from alpha; and __fish_seen_subcommand_from common")
    );
    assert!(
        beta.contains("__fish_seen_subcommand_from beta; and __fish_seen_subcommand_from common")
    );
}

