#[test]
fn escapes_choice_values_for_both_the_string_quoting_and_the_expansion_of_the_a_list() {
    // :618
    let script = fish::generate("deploy", &tricky());
    let lines: Vec<&str> = script
        .lines()
        .filter(|line| line.contains("-r -f -a"))
        .collect();
    assert_eq!(
        lines.join("\n"),
        r#"complete -c deploy -n 'begin; not __fish_contains_opt mode; or contains -- (commandline -poc)[-1] --mode; end' -l mode -d 'Deploy mode' -r -f -a 'it\\\'s-fine node\\:20 with\\ space \\(whoami\\) \\#tag \\$HOME back\\\\slash say\\"hi\\" a\\*b a\\;b \\~x foo\\\' a\\!b \\🚀'
complete -c deploy -r -f -a 'o\\\'clock a\\:b \\{x,y\\} a\\😀b' -d 'Deployment target'"#
    );
}

