#[test]
fn generates_used_flag_dedup_conditions() {
    // :675
    let script = fish::generate("greet", &simple());
    assert!(script.contains("not __fish_contains_opt -s l loud no-loud"));
    let times_long = script
        .lines()
        .find(|line| line.contains("-l times"))
        .expect("times -l entry missing");
    assert!(times_long.contains(
        "-n 'begin; not __fish_contains_opt times; or contains -- (commandline -poc)[-1] --times; end'"
    ));
    let times_arg = script
        .lines()
        .find(|line| line.contains("-a '--times'"))
        .expect("times -a entry missing");
    assert!(times_arg.contains("not __fish_contains_opt times"));
}

#[test]
fn combines_subcommand_and_dedup_conditions() {
    // :690
    let script = fish::generate("server", &server());
    assert!(script.contains(
        "__fish_seen_subcommand_from start; and not __fish_contains_opt daemon no-daemon"
    ));
    let port_long = script
        .lines()
        .find(|line| line.contains("-l port"))
        .expect("port -l entry missing");
    assert!(port_long.contains(
        "-n '__fish_seen_subcommand_from start; and begin; not __fish_contains_opt -s p port; or contains -- (commandline -poc)[-1] --port -p; end'"
    ));
    let port_arg = script
        .lines()
        .find(|line| line.contains("-a '--port'"))
        .expect("port -a entry missing");
    assert!(port_arg.contains("not __fish_contains_opt -s p port"));
}

