#[test]
fn adds_a_entries_for_flags_so_they_appear_on_bare_tab() {
    // :740
    let script = fish::generate("greet", &simple());
    let loud = script
        .lines()
        .find(|line| line.contains("-a '--loud'"))
        .expect("--loud -a entry missing");
    assert!(loud.contains("not string match -q -- \"-*\" (commandline -ct)"));
    assert!(loud.contains("not __fish_contains_opt"));
    let times = script
        .lines()
        .find(|line| line.contains("-a '--times'"))
        .expect("--times -a entry missing");
    assert!(times.contains("not string match -q -- \"-*\" (commandline -ct)"));
    assert!(script.lines().any(|line| line.contains("-a '--no-loud'")));
}

#[test]
fn bare_tab_a_entries_use_double_quotes_around_glob_pattern() {
    // :758
    let script = fish::generate("greet", &simple());
    let arg_entries: Vec<&str> = script
        .lines()
        .filter(|line| line.contains(" -a '--"))
        .collect();
    assert!(!arg_entries.is_empty());
    for line in arg_entries {
        assert!(
            line.contains("\"-*\""),
            "double-quoted glob expected: {line}"
        );
        assert!(
            !line.contains("'-*'"),
            "single-quoted glob must not appear: {line}"
        );
    }
}

#[test]
fn does_not_suppress_file_completion_for_commands_with_path_arguments() {
    // :772
    let script = fish::generate("process", &paths());
    // A bare `-f` suppression line carries no -l/-a/-r/-F.
    let bare_suppression = script.lines().any(|line| {
        line.starts_with("complete -c process")
            && line.ends_with(" -f")
            && !line.contains("-l ")
            && !line.contains("-a ")
            && !line.contains("-r ")
            && !line.contains("-F")
    });
    assert!(
        !bare_suppression,
        "commands with path arguments should not suppress file completion"
    );
}

#[test]
fn generates_valid_fish_script_for_comprehensive_cli() {
    // :885
    let script = fish::generate("mycli", &comprehensive());
    // Same assertion set as the pin's ComprehensiveCli integration row.
    for expected in [
        "complete -c mycli",
        "-a 'admin'",
        "-a 'copy'",
        "-a 'build'",
        "-a 'git'",
        "-l debug",
        "-s d",
        "-l quiet",
        "-s q",
        "-l no-debug",
        "-l no-quiet",
        "-d 'Administrative commands'",
        "-d 'Build the project'",
        "__fish_use_subcommand",
        "__fish_seen_subcommand_from admin",
        "__fish_seen_subcommand_from git",
    ] {
        assert!(
            script.contains(expected),
            "fish script missing {expected:?}"
        );
    }
}
